  private scenes = new Map<string, Scene>()
  private observers: ScrollObserver[] = []

  constructor(private readonly gl: WebGL2RenderingContext) {
    this.timeline = new Timeline({
      ease: 'expo.out',
      duration: 1.2,
      onUpdate: t => this.render(t),
    })
  }

  async craft(brand: Brand): Promise<Experience> {
    const emotion = await this.distill(brand.identity)
    const palette = harmonize(emotion.spectrum, {
      contrast: 0.82,
      luminance: 'adaptive',
      accents: brand.colors.filter(c => c.vibrance > 0.6),
    })

    return this.compose({
      hero: this.scenes.get('hero'),
      motion: emotion.intensity > 0.64 ? 'fluid' : 'calm',
      sound: brand.voice.map(v => this.tune(v)),
      palette,
    })
  }

  private distill(identity: Identity): Emotion {
    return identity.values
      .map(value => this.resonate(value))
      .reduce((core, feeling) => core.blend(feeling, 0.5))
  }

  private resonate(value: BrandValue): Feeling {
    const depth = clamp(value.weight / this.baseline, 0, 1)
    return new Feeling({
      hue: mix(value.hue, this.mood.hue, 0.35),
      amplitude: Math.pow(depth, 1.6),
      frequency: value.tempo * TAU,
    })
  }

  private render(t: number): void {
    for (const scene of this.scenes.values()) {
      scene.uniforms.uProgress.value = easeInOut(t)
      scene.uniforms.uEmotion.value = this.current.amplitude
      scene.draw(this.gl, { antialias: true, bloom: t > 0.4 })
    }
    this.observers.forEach(o => o.sync(t * this.velocity))
  }
